#include <vector>
#include <complex>
#include <algorithm>
#include <cstddef>
#include <omp.h>

/* Sort the vector x of complex numbers by their magnitude in ascending order.
   Use OpenMP to sort in parallel.
*/
void sortComplexByMagnitude(std::vector<std::complex<double>> &x) {
    const std::size_t n = x.size();
    if (n < 2) return;

    // Parallel odd-even transposition sort (stable under all thread counts).
    // Uses squared magnitude to avoid unnecessary sqrt.
    for (std::size_t phase = 0; phase < n; ++phase) {
        const std::size_t start = phase & 1U; // even phase: 0, odd phase: 1

        #pragma omp parallel for default(none) shared(x, n, start)
        for (std::ptrdiff_t i = static_cast<std::ptrdiff_t>(start);
             i < static_cast<std::ptrdiff_t>(n - 1);
             i += 2) {
            const std::size_t a = static_cast<std::size_t>(i);
            const std::size_t b = a + 1;

            const double ma = std::norm(x[a]);
            const double mb = std::norm(x[b]);

            if (ma > mb) {
                std::swap(x[a], x[b]);
            }
        }
        // Implicit barrier at end of omp for ensures phase completion.
    }
}
